  const wasEmpty = !a.path.length; a.path = a.path.concat(p); a.dest = pid; a.mode = null; a.joinTo = null;
  if (wasEmpty && p.length) { a.hop = hopDays(a, a.loc, p[0]); a.hopMax = a.hop; }
  return {ok: true, eta: armyEta(a)};
