  if (tf.hamlet && !isAtt) def += 0.03; if (tf.rocks && tf.rocks.length && !isAtt) def += 0.02; if (tf.marsh && tf.marsh.length && isAtt && b.day <= 3) att -= 0.02;
  if (typeof tacMods === 'function') { const pm = tacMods(b, side); att += pm.att; def += pm.def; }
