function natStart(c, id) {
  c.nat = c.nat || {done: [], cur: null};
  const n = natNode(c, id); if (!n) return {ok: false, msg: 'Decisión desconocida.'};
  const st = natState(c, n); if (st.k !== 'avail') return {ok: false, msg: st.why || 'No disponible.'};
  if (c.nat.cur) return {ok: false, msg: 'Ya hay una decisión en curso.'};
  c.nat.cur = {id, left: Math.round(n.days * (1 + (G.diff >= 3 ? 0.15 : 0)) * (c.ai ? 1.8 : 1)), total: n.days};
  return {ok: true, msg: `Comienza la decisión «${n.name}» (${Math.round(c.nat.cur.left / 7)} semanas).`};
}
function natDay() {
  G.tags.forEach(t => {
    if (t === NONE) return; const c = G.C[t]; if (!c.states.length) return;
    c.nat = c.nat || {done: [], cur: null};
    if (c.nat.cur) {
      if (--c.nat.cur.left <= 0) {
        const n = natNode(c, c.nat.cur.id); c.nat.done.push(n.id); c.nat.cur = null; applyNatFx(c, n.fx); cnt(c, 'natDone');
        if (t === G.player) notify('journal', `Decisión nacional completada: «${n.name}». ${natFxText(n.fx)}`);
      }
    } else if (c.ai && G.date.d === 1 && Math.random() < 0.22) {         // la IA elige una decisión disponible
      const av = natTree(c).filter(n => natState(c, n).k === 'avail'); if (!av.length) return;
      const w = av.map(n => 1 + n.fx.filter(f => f[0] === 'mod').length * 0.5 + (c.wars.length && n.fx.some(f => f[0] === 'divs') ? 2 : 0));
      let r = Math.random() * w.reduce((a, b) => a + b, 0), pk = av[0]; for (let i = 0; i < av.length; i++) { r -= w[i]; if (r <= 0) { pk = av[i]; break; } }
      natStart(c, pk.id);
    }
  });
}
/* ---------- ventana ---------- */
const NAT_CW = 230, NAT_CH = 132;
WINDOWS.national = {title: 'Decisiones nacionales', icon: '🌳', render() {
  const c = me(); c.nat = c.nat || {done: [], cur: null};
  const tree = natTree(c), br = natBranches(c), cur = c.nat.cur && natNode(c, c.nat.cur.id);
  const W = br.length * NAT_CW + 20, H = (Math.max(...tree.map(n => n.t)) + 1) * NAT_CH + 50;
  const pos = n => ({x: 10 + n.b * NAT_CW + 15, y: 40 + n.t * NAT_CH});
  const lines = tree.map(n => n.req.map(r => { const p = natNode(c, r), a = pos(p), b = pos(n); return `<path d="M${a.x + 100} ${a.y + 86} C${a.x + 100} ${a.y + 112} ${b.x + 100} ${b.y - 24} ${b.x + 100} ${b.y}" class="nl"/>`; }).join('') + n.excl.map(x => { const p = natNode(c, x); if (!p || p.id < n.id) return ''; const a = pos(p), b = pos(n); return `<path d="M${a.x + 200} ${a.y + 43} L${b.x} ${b.y + 43}" class="nl ex"/>`; }).join('')).join('');
  const nodes = tree.map(n => { const st = natState(c, n), p = pos(n); const cu = st.k === 'cur' ? c.nat.cur : null;
    return `<div class="nnode ${st.k}" style="left:${p.x}px;top:${p.y}px" ${st.k === 'avail' ? `data-act="natstart" data-id="${n.id}"` : ''}><div class="nh"><span class="ni">${n.icon}</span><b>${n.name}</b></div><small>${n.desc}</small><small class="nfx">${natFxText(n.fx)}</small>
      ${cu ? `<div class="bar"><i style="width:${(1 - cu.left / (cu.total * 1.15)) * 100}%"></i></div><small>${Math.ceil(cu.left / 7)} semanas</small>` : st.k === 'done' ? '<small class="good">✔ Completada</small>' : st.k === 'avail' ? `<small class="dim">⏱ ${Math.round(n.days / 7)} semanas — clic para comenzar</small>` : `<small class="dim">${st.why || ''}</small>`}</div>`; }).join('');
  return `<div class="card"><div class="kv"><b>${NAT_BRANCHES[c.tag] ? '🌳 Árbol de ' + c.name : '🌳 Árbol genérico'}</b>${cur ? `<span>En curso: <b>${cur.name}</b> · ${Math.ceil(c.nat.cur.left / 7)} semanas <button data-act="natcancel">Cancelar</button></span>` : '<span class="good">Elige tu próxima decisión</span>'}</div>
  <p class="hint">Cada decisión tarda entre 10 y 20 semanas y sus efectos son permanentes. Las ramas con línea roja son <b>excluyentes</b>: elegir una bloquea la otra.</p>
  <div class="ntree scrollable"><div class="ncanvas" style="width:${W}px;height:${H}px"><svg width="${W}" height="${H}">${lines}</svg>${br.map((b, i) => `<div class="nbr" style="left:${10 + i * NAT_CW + 15}px"><b>${b}</b></div>`).join('')}${nodes}</div></div></div>`;
}};
Object.assign(ACT, {
  natstart: d => { const r = natStart(me(), d.id); toast(r.ok ? '🌳' : '⚠️', r.msg); renderWindow(true); },
  natcancel: () => { me().nat.cur = null; renderWindow(true); }
});

/* ===== CONFERENCIAS DE PAZ: el vencedor gasta su puntuación de guerra en exigencias ===== */
const LAW_DEMANDS = {
  army: {cat: 'army', opt: 'peasant_levies', name: 'Ejército de levas campesinas (sin ejército profesional)'},
  economy: {cat: 'economy', opt: 'laissez', name: 'Apertura de mercados (laissez-faire)'},
  press: {cat: 'press', opt: 'censorship', name: 'Régimen de censura'}
};
function buildConference(w, winner) {
  const att = winner === w.att, winAll = (att ? w.attAll : w.defAll).slice(), loseAll = (att ? w.defAll : w.attAll).slice(), loseLead = att ? w.def : w.att;
  const budget = clamp(Math.abs(w.score), 30, 100), opts = [];
  G.S.forEach(s => {
    if (!loseAll.includes(s.owner)) return;
    const occ = s.occ && s.occBy && winAll.includes(s.occBy) ? s.occ : 0, target = att && w.targets.includes(s.id);
    if (occ < 0.2 && !target) return;
    const pop = popTotal(s);
    let cost = 4 + Math.sqrt(pop / 1e5) * 2.4;
    cost *= occ >= 0.5 ? 1 : occ > 0 ? 1.5 : 2.4;
    if (target) cost *= 0.5;
    if (G.C[s.owner].capital === s.id) cost *= 1.5;
    opts.push({id: 's' + s.id, type: 'state', sid: s.id, cost: Math.round(clamp(cost, 4, 40)), occ, target, pop});
  });
  opts.sort((a, b) => b.pop - a.pop); opts.length = Math.min(opts.length, 22);
  const L = G.C[loseLead], W = G.C[winner];
  opts.push({id: 'reps8', type: 'reps', weeks: 8, cost: 10}, {id: 'reps16', type: 'reps', weeks: 16, cost: 20});
  opts.push({id: 'humil', type: 'humil', cost: 12}, {id: 'trade', type: 'trade', cost: 12}, {id: 'demil', type: 'demil', cost: 15});
  Object.keys(LAW_DEMANDS).forEach(k => { if (L.laws[LAW_DEMANDS[k].cat] !== LAW_DEMANDS[k].opt) opts.push({id: 'law_' + k, type: 'law', key: k, cost: 20}); });
  if (!L.overlord && !W.overlord && L.stats.pop < W.stats.pop * 1.5) opts.push({id: 'vassal', type: 'vassal', cost: 45});
  return {w, winner, winAll, loseAll, loseLead, budget, opts, pick: new Set(), recip: {}};
}
const confSpent = c => c.opts.reduce((n, o) => n + (c.pick.has(o.id) ? o.cost : 0), 0);
function confLabel(c, o) {
  const W = G.C[c.winner], L = G.C[c.loseLead];
  if (o.type === 'state') return `Anexionar ${G.S[o.sid].name}`;
  if (o.type === 'reps') return `Reparaciones de guerra (${o.weeks} semanas de ingresos de ${L.name})`;
  if (o.type === 'humil') return `Humillar a ${L.name}: −12 prestigio para ellos, +12 para ti`;
  if (o.type === 'trade') return `Concesiones comerciales: pacto de comercio forzoso y pérdida de ingresos aduaneros`;
  if (o.type === 'demil') return `Desmilitarización: ${L.name} licencia el 60% de su ejército`;
  if (o.type === 'law') return `Imponer ley: ${LAW_DEMANDS[o.key].name}`;
  if (o.type === 'vassal') return `Convertir a ${L.name} en tu vasallo`;
  void W; return o.id;
}
// elección automática de la IA: objetivos de guerra primero, luego territorios más valiosos, luego dinero y prestigio
function aiPickDemands(c) {
  let left = c.budget;
  const val = o => o.type === 'state' ? (o.target ? 3 : 1.2) * (o.pop / 1e6 + 0.5) / o.cost * 10 : o.type === 'reps' ? 0.9 : o.type === 'humil' ? 0.7 : o.type === 'vassal' ? 0.5 : o.type === 'demil' ? 0.4 : o.type === 'trade' ? 0.3 : 0.1;
  c.opts.slice().sort((a, b) => val(b) - val(a)).forEach(o => {
    if (o.type === 'state' && typeof aiMayTake === 'function' && !aiMayTake(c.winner, o.sid)) return;
    if (o.cost > left) return; if (o.type === 'reps' && c.pick.has('reps8') && o.id === 'reps16') return; if (o.type === 'law') return;
    if (o.type === 'vassal' && c.pick.size) return;
    c.pick.add(o.id); left -= o.cost;
    if (o.type === 'state') { const L = c.winAll.filter(t => t !== c.winner && alive(t)); c.recip[o.sid] = L.length && Math.random() < 0.18 ? pick(L) : c.winner; }
  });
}
function applyConference(c) {
  const w = c.w, W = G.C[c.winner], L = G.C[c.loseLead], gained = [], notes = [];
  c.opts.forEach(o => {
    if (!c.pick.has(o.id)) return;
    if (o.type === 'state') { const s = G.S[o.sid]; if (!loseAllHas(c, s.owner)) return; const r = c.recip[o.sid] || c.winner; transferState(s, r); gained.push(s.name + (r !== c.winner ? ` (para ${G.C[r].name})` : '')); }
    else if (o.type === 'reps') { const ind = Math.min(Math.max(0, L.treasury), L.stats.income * o.weeks); L.treasury -= ind; W.treasury += ind; notes.push(`reparaciones de ${money(ind)}`); }
    else if (o.type === 'humil') { W.prestige += 12; L.prestige = Math.max(0, L.prestige - 12); cnt(W, 'humiliations'); notes.push('humillación'); }
    else if (o.type === 'trade') { L.tradeLoss = Math.min(0.25, (L.tradeLoss || 0) + 0.06); makePact('trade', c.winner, c.loseLead, {forced: true}); notes.push('concesiones comerciales'); }
    else if (o.type === 'demil') { G.armies.forEach(a => { if (a.tag === c.loseLead) { a.divs = a.divs.slice(0, Math.ceil(a.divs.length * 0.4)); } }); G.armies = G.armies.filter(a => a.divs.length); L.mob = 0; notes.push('desmilitarización'); }
    else if (o.type === 'law') { const d = LAW_DEMANDS[o.key]; L.laws[d.cat] = d.opt; recalcMods(L); L.legitimacy -= 10; L.radicals = Math.min(0.9, L.radicals + 0.06); notes.push('ley impuesta'); }
    else if (o.type === 'vassal') { makeSubject(c.winner, c.loseLead); cnt(W, 'vassalsMade'); notes.push('vasallaje'); }
  });
  const att = c.winner === w.att;
  if (c.negotiated) { W.prestige += 3 + gained.length * 2; cnt(W, 'statesGained', gained.length); L.prestige = Math.max(0, L.prestige - 3); L.wear = Math.max(0, (L.wear || 0) - 25); W.wear = Math.max(0, (W.wear || 0) - 15); }
  else {
  W.prestige += 6 + gained.length * 4; cnt(W, 'statesGained', gained.length); cnt(W, 'warsWon'); if (!att) cnt(W, 'defended');
  L.prestige = Math.max(0, L.prestige - 8); L.legitimacy -= 4; L.wear = Math.max(0, (L.wear || 0) - 20); }
  c.winAll.forEach(t => { if (t !== c.winner && alive(t)) G.C[t].prestige += 3; });
  addRel(c.winner, c.loseLead, att ? 20 : 10);
  const txt = c.negotiated ? `paz negociada entre ${W.name} y ${L.name}` : att ? `${W.name} vence a ${L.name}` : `${W.name} repele la invasión de ${L.name}`;
  notify('war', `Conferencia de paz: ${txt}${gained.length ? ' y se anexiona ' + gained.join(', ') : ''}${notes.length ? '. Además: ' + notes.join(', ') : ''}.`, c.pick.size && gained.length ? c.opts.find(o => o.type === 'state' && c.pick.has(o.id)).sid : undefined);
  G.tags.forEach(t => { if (t !== NONE) G.C[t].legitimacy = clamp(G.C[t].legitimacy, 0, 100); });
  recalcHostile(); evacuateForeignArmies(); if (typeof fullRepaint === 'function' && gained.length) fullRepaint();
}
const loseAllHas = (c, tag) => c.loseAll.includes(tag);
function endWar(w, winner, preset) {
  const rep = typeof warReport === 'function' ? warReport(w, winner) : null;
  endWarCore(w, winner, preset);
  w.attAll.concat(w.defAll).forEach(t => { if (G.C[t]) G.C[t].lastWar = G.date.t; });
  if (rep && rep.mine && typeof showWarSummary === 'function') showWarSummary(rep);
}
function endWarCore(w, winner, preset) {
  const idx = G.wars.indexOf(w); if (idx >= 0) G.wars.splice(idx, 1);
  if (typeof returnPrisoners === 'function') returnPrisoners(w);
  const conf = winner !== null && !w.auto ? buildConference(w, winner) : null;      // antes de borrar las ocupaciones
  clearOccupationKeep(w);
  w.attAll.concat(w.defAll).forEach(t => { const c = G.C[t]; c.wars = c.wars.filter(x => x !== w.id); });
  const A = G.C[w.att], D = G.C[w.def];
  if (winner === null) { notify('war', `${A.name} y ${D.name} firman una paz blanca.`); addRel(w.att, w.def, 25); return; }
  if (w.auto) { settleLegacy(w, winner); return; }
  if (preset && conf) { conf.pick = new Set(preset.ids); conf.negotiated = !!preset.negotiated; applyConference(conf); return; }
  const humanLead = !G.C[winner].ai && typeof openConference === 'function' && !G.headless;
  if (humanLead) { G.confQueue = G.confQueue || []; G.confQueue.push(conf); if (!G.conf) nextConference(); }
  else { aiPickDemands(conf); applyConference(conf); }
}
function nextConference() {
  G.conf = (G.confQueue || []).shift() || null;
  if (G.conf) { G.paused = true; openConference(); } else closeConference();
}
function settleLegacy(w, winner) {
  const A = G.C[w.att], D = G.C[w.def];
  const attWins = winner === w.att;
  const cb = CBS[w.cb];
  const occ = {};
  if (attWins) {
    const full = Math.abs(w.score) >= 85;
    let gained = [];
    if (cb.terr) {
      w.targets.forEach(sid => { const s = G.S[sid]; if (s && s.owner === w.def && (full || (s.occ || 0) >= 0.5 || w.score >= 60)) { transferState(s, w.att); gained.push(s.name); } });
      A.prestige += 6 + gained.length * 4; cnt(A, 'statesGained', gained.length);
    } else if (w.cb === 'humiliate') {
      const ind = Math.min(Math.max(0, D.treasury), D.stats.income * 8); D.treasury -= ind; A.treasury += ind;
      A.prestige += 12; D.prestige = Math.max(0, D.prestige - 12);
    } else if (w.cb === 'regime' && w.law) {
      D.laws[w.law.cat] = w.law.opt; recalcMods(D); D.legitimacy -= 12; D.radicals = Math.min(0.9, D.radicals + 0.08); A.prestige += 8;
    } else if (w.cb === 'trade') {
      const ind = Math.min(Math.max(0, D.treasury), D.stats.income * 5); D.treasury -= ind; A.treasury += ind;
      D.tradeLoss = Math.min(0.25, (D.tradeLoss || 0) + 0.06); makePact('trade', w.att, w.def, {forced: true}); A.prestige += 8;
    } else if (w.cb === 'vassal') {
      makeSubject(w.att, w.def); A.prestige += 15; cnt(A, 'vassalsMade');
    }
    D.prestige = Math.max(0, D.prestige - 8); D.legitimacy -= 4; cnt(A, 'warsWon'); if (w.cb === 'humiliate') cnt(A, 'humiliations');
    notify('war', `${A.name} ha vencido a ${D.name}${gained.length ? ' y se anexiona ' + gained.join(', ') : ' (' + cb.name + ')'}.`, w.targets[0]);
    // aliados del vencedor ganan prestigio
    w.attAll.forEach(t => { if (t !== w.att) G.C[t].prestige += 3; });
    addRel(w.att, w.def, 20);
  } else {
    const ind = Math.min(Math.max(0, A.treasury), A.stats.income * 4); A.treasury -= ind; D.treasury += ind;
    D.prestige += 8; A.prestige = Math.max(0, A.prestige - 10); A.legitimacy -= 5;
    const regained = [];
    G.S.filter(s => s.owner === w.att && (s.occ || 0) >= 0.5 && w.defAll.includes(s.occBy)).sort((x, y) => y.popBase - x.popBase).slice(0, 3).forEach(s => { transferState(s, w.def); regained.push(s.name); });
    notify('war', `${D.name} ha repelido la invasión de ${A.name}${regained.length ? ' y se anexiona ' + regained.join(', ') : ''}.`, w.cTargets[0] ?? w.targets[0]);
    addRel(w.att, w.def, 10); cnt(D, 'defended'); cnt(D, 'warsWon'); cnt(D, 'statesGained', regained.length);
  }
  G.tags.forEach(t => { if (t !== NONE) G.C[t].legitimacy = clamp(G.C[t].legitimacy, 0, 100); });
  recalcHostile(); evacuateForeignArmies();
}

/* ---------- ventana de la conferencia ---------- */
function openConference() { renderConference(); }
function closeConference() { const r = $('#confdlg'); if (r) { r.classList.remove('open'); r.innerHTML = ''; } }
function renderConference() {
  const c = G.conf, root = $('#confdlg'); if (!root) return; if (!c) { closeConference(); return; }
  const W = G.C[c.winner], L = G.C[c.loseLead], w = c.w, spent = confSpent(c), left = c.budget - spent;
  const states = c.opts.filter(o => o.type === 'state'), others = c.opts.filter(o => o.type !== 'state');
  const row = o => `<label class="cfrow ${c.pick.has(o.id) ? 'on' : ''}"><input type="checkbox" data-act="confpick" data-id="${o.id}" ${c.pick.has(o.id) ? 'checked' : ''} ${!c.pick.has(o.id) && o.cost > left ? 'disabled' : ''}>
    <span class="cfl">${confLabel(c, o)}${o.type === 'state' ? `<small class="dim"> · ${fmtN(o.pop, 1)} hab. · ${o.target ? '🎯 objetivo de guerra · ' : ''}${o.occ >= 0.5 ? 'ocupado' : o.occ > 0 ? 'ocupado en parte' : 'sin ocupar (más caro)'}</small>` : ''}</span>
    ${o.type === 'state' && c.pick.has(o.id) && c.winAll.filter(t => t !== c.winner && alive(t)).length ? `<select data-act="confrecip" data-id="${o.sid}"><option value="${c.winner}">Para mí</option>${c.winAll.filter(t => t !== c.winner && alive(t)).map(t => `<option value="${t}" ${c.recip[o.sid] === t ? 'selected' : ''}>Para ${G.C[t].name}</option>`).join('')}</select>` : ''}
    <b class="cfc">${o.cost} pts</b></label>`;
  root.classList.add('open');
  root.innerHTML = `<div class="wd"><div class="whead"><span class="wicon">🕊️</span><h2>Conferencia de paz — ${w.name || CBS[w.cb].name}</h2></div>
  <div class="wd-body"><div class="cols"><div class="col wide">
    <div class="notice">${flag(c.winner, 'sm')} <b>${W.name}</b> ha vencido a ${flag(c.loseLead, 'sm')} <b>${L.name}</b>. Gasta tus <b>puntos de guerra</b> en las exigencias que quieras.</div>
    <h4 class="sub">Territorios</h4>${states.length ? states.map(row).join('') : '<p class="hint">No hay territorios ocupados que reclamar.</p>'}
    <h4 class="sub">Otras exigencias</h4>${others.map(row).join('')}
  </div><div class="col">
    <div class="card"><h3>Puntos de guerra</h3><div class="kv"><span>Disponibles</span><b>${c.budget}</b></div><div class="kv"><span>Gastados</span><b>${spent}</b></div><div class="kv"><span>Restantes</span><b class="${left < 0 ? 'bad' : 'good'}">${left}</b></div>${bar(spent, c.budget, left < 0 ? 'bad' : 'warn')}
    <p class="hint">La puntuación de la guerra (${Math.round(Math.abs(w.score))}) fija el presupuesto. Los territorios ocupados y los objetivos de guerra son más baratos.</p>
    <div class="btnrow"><button class="primary" data-act="confsign" ${left < 0 ? 'disabled' : ''}>✍️ Firmar la paz${c.pick.size ? '' : ' (sin exigencias)'}</button></div></div>
    <div class="card"><h3>Aliados en el bando vencedor</h3>${c.winAll.filter(t => t !== c.winner).map(t => `<div class="kv sm"><span>${flag(t, 'sm')} ${G.C[t].name}</span></div>`).join('') || '<small class="dim">Ninguno.</small>'}<p class="hint">Puedes ceder territorios a tus aliados para ganar su favor.</p></div>
  </div></div></div></div>`;
}
Object.assign(ACT, {
  confpick: (d, el) => { const c = G.conf; if (!c) return; if (el.checked) c.pick.add(d.id); else c.pick.delete(d.id); renderConference(); },
  confrecip: (d, el) => { if (G.conf) G.conf.recip[+d.id] = el.value; },
  confsign: () => { const c = G.conf; if (!c || confSpent(c) > c.budget) return; applyConference(c); G.conf = null; nextConference(); if (!G.conf) { G.paused = false; updateHud(); } renderWindow && renderWindow(); }
});

/* ===== COALICIONES CONTRA EL EXPANSIONISMO: las potencias se alían para frenar a quien acumula infamia o conquistas ===== */
const threatOf = c => c.infamy * 0.7 + (c.exp || 0) * 2;
const coalitionOf = tag => (G.coals || []).find(x => x.target === tag);
const inCoalition = tag => (G.coals || []).find(x => x.members.includes(tag));
function coalCandidate(tag, target) {
  if (!alive(tag) || tag === target || G.C[tag].overlord || G.C[target].overlord === tag || (G.C[target].subjects || []).includes(tag)) return false;
  if (G.C[tag].bloc && G.C[tag].bloc === G.C[target].bloc) return false;
  if (anyPactBetween(tag, target, ['alliance', 'guarantee'])) return false;
  if (!G.C[tag].ai && tag !== G.player) return false;
  return true;
}
function coalPower(list) { return crisisPower(list); }
function createCoalition(target) {
  const T = G.C[target], tp = armyPower(T) + allies(target).reduce((n, t) => n + (alive(t) ? armyPower(G.C[t]) : 0), 0);
  const cand = G.tags.filter(t => t !== NONE && G.C[t].ai && coalCandidate(t, target) && G.C[t].rank <= 22)
    .map(t => ({t, w: (relOf(t, target) < 25 ? 1.5 : 0.5) * (minDist(G.C[t], T).min < 50 ? 1.6 : 0.6) * (1 + G.C[t].rank <= 8 ? 1.3 : 1) * (0.6 + Math.random())}))
    .sort((a, b) => b.w - a.w).slice(0, 6);
  const members = cand.map(x => x.t); if (members.length < 3) return null;
  if (coalPower(members) < tp * 0.45) return null;
  const leader = members.slice().sort((a, b) => armyPower(G.C[b]) - armyPower(G.C[a]))[0];
  G.coals = G.coals || []; G.nextCoal = G.nextCoal || 1;
  const co = {id: G.nextCoal++, target, leader, members, age: 0};
  G.coals.push(co);
  const names = members.map(t => G.C[t].name).join(', ');
  if (target === G.player) notify('diplo', `¡Se forma una coalición contra ti! ${G.C[leader].name} lidera a ${names} para frenar tu expansión. Revisa Diplomacia → Coaliciones.`, G.C[leader].capital);
  else logMsg(`Coalición contra ${T.name}, liderada por ${G.C[leader].name} (${names}).`);
  return co;
}
function dissolveCoalition(co, why) {
  G.coals = G.coals.filter(x => x !== co);
  if (co.target === G.player) notify('diplo', `La coalición contra ti se disuelve${why ? ' (' + why + ')' : ''}.`);
}
function coalitionsMonth() {
  G.coals = G.coals || []; aiBullyPlayer();
  G.tags.forEach(t => { if (t !== NONE) { const c = G.C[t]; c.exp = (c.exp || 0) * 0.97; } });
  G.tags.forEach(t => {
    if (t === NONE || !alive(t)) return; const c = G.C[t], th = threatOf(c), co = coalitionOf(t);
    if (!co) { if (th >= 32 && Math.random() < clamp((th - 30) / 110, 0, 0.35)) createCoalition(t); return; }
    co.age++;
    // salen miembros reconciliados o muertos
    co.members = co.members.filter(m => alive(m) && !anyPactBetween(m, t, ['alliance', 'guarantee']) && relOf(m, t) < 48 && !(th < 18 && Math.random() < 0.2));
    // entran nuevos
    if (co.members.length < 8 && th > 28) { const cand = G.tags.filter(x => x !== NONE && !co.members.includes(x) && G.C[x].ai && G.C[x].rank <= 24 && coalCandidate(x, t) && relOf(x, t) < 30 && minDist(G.C[x], c).min < 60); if (cand.length && Math.random() < clamp((th - 26) / 140, 0, 0.3)) { const x = pick(cand); co.members.push(x); if (t === G.player) notify('diplo', `${G.C[x].name} se une a la coalición contra ti.`); } }
    if (!alive(co.leader) || !co.members.includes(co.leader)) co.leader = co.members.slice().sort((a, b) => armyPower(G.C[b]) - armyPower(G.C[a]))[0];
    if (co.members.length < 2 || (th < 14 && co.age > 12)) { dissolveCoalition(co, th < 14 ? 'ya no representas una amenaza' : 'quedan pocos miembros'); return; }
    // presión diplomática
    co.members.forEach(m => { addRel(m, t, -1.5); co.members.forEach(n => { if (m < n) addRel(m, n, 0.4); }); });
    // la IA líder presiona con una crisis diplomática cuando se siente fuerte
    const L = G.C[co.leader];
    if (L && L.ai && !crisisOf(co.leader) && !crisisOf(t) && !L.wars.length && !c.wars.some(wid => { const w = G.wars.find(x => x.id === wid); return w && w.attAll.concat(w.defAll).includes(co.leader); })) {
      const tp = armyPower(c) + allies(t).reduce((n, x) => n + (alive(x) ? armyPower(G.C[x]) : 0), 0), mp = coalPower(co.members);
      if (mp >= tp * 0.85 && th > 34 && Math.random() < 0.1 * diffP().crisis) coalitionStrike(co);
    }
  });
}
// grandes potencias hostiles intimidan al jugador si es mucho más débil
function aiBullyPlayer() {
  const P = G.C[G.player]; if (!P || crisisOf(G.player) || P.wars.length) return;
  const pp = armyPower(P) + allies(G.player).reduce((n, t) => n + (alive(t) ? armyPower(G.C[t]) : 0), 0);
  G.tags.forEach(t => {
    if (t === NONE || t === G.player || !alive(t) || crisisOf(G.player)) return; const A = G.C[t];
    if (!A.ai || A.rank > 12 || A.wars.length || A.overlord || crisisOf(t) || relOf(t, G.player) > 15) return;
    if (armyPower(A) < pp * 1.6 || !canReach(t, G.player) || anyPactBetween(t, G.player, ['alliance', 'guarantee', 'nonagg'])) return;
    if (Math.random() > 0.012 * diffP().crisis * (1 + threatOf(P) / 40)) return;
    const cb = ['claim', 'humiliate', 'trade'].find(k => cbAvailable(t, G.player, k).ok); if (!cb) return;
    const targets = CBS[cb].terr ? claimedStates(A, G.player).slice(0, 2).map(x => x.id) : [];
    const r = openCrisis(t, G.player, cb, targets, {free: true, ai: true});
    if (r.ok) notify('diplo', `${A.name}, más fuerte que tú, te presiona con una crisis diplomática (${CBS[cb].name.toLowerCase()}). Elige en Diplomacia → Crisis.`, A.capital);
  });
}
function coalitionStrike(co) {
  const L = co.leader, T = co.target, A = G.C[L];
  const cbs = ['claim', 'humiliate', 'trade', 'conquest'].filter(k => cbAvailable(L, T, k).ok && !(k === 'conquest' && A.influence < 0));
  if (!cbs.length || !canReach(L, T)) return;
  const cb = cbs[0]; let targets = [];
  if (CBS[cb].terr) targets = (cb === 'claim' ? claimedStates(A, T) : reachableStates(L, T)).slice(0, 2).map(x => x.id);
  const r = openCrisis(L, T, cb, targets, {free: true, ai: true}); if (!r.ok) return;
  co.members.forEach(m => { if (m !== L) crisisJoin(r.crisis, m, 'att', 'coalición'); });
  if (T === G.player) notify('diplo', `La coalición liderada por ${A.name} te exige ${CBS[cb].name.toLowerCase()}. ¡Elige en Diplomacia → Crisis: ceder o resistir!`, G.C[L].capital);
}
// los miembros acuden a frenar al país amenazante cuando está en guerra (o a defender a sus víctimas)
function coalitionCall(w) {
  [[w.att, 'def'], [w.def, 'att']].forEach(([tg, side]) => {
    const co = coalitionOf(tg); if (!co) return;
    co.members.forEach(m => {
      if (!alive(m) || w.attAll.includes(m) || w.defAll.includes(m) || G.C[m].wars.length >= 2) return;
      const mine = side === 'def' ? w.defAll : w.attAll;
      if (mine.some(x => anyPactBetween(m, x, ['alliance'])) && false) return;
      if (Math.random() < 0.85) { mine.push(m); G.C[m].wars.push(w.id); if (m === G.player) notify('war', 'Tu país entra en la guerra para frenar a ' + G.C[tg].name + '.'); else logMsg(`${G.C[m].name} acude desde la coalición contra ${G.C[tg].name}.`); }
    });
  });
}
function coalitionsHtml() {
  const mine = (G.coals || []).filter(x => x.target === G.player), others = (G.coals || []).filter(x => x.target !== G.player), c = me();
  const th = threatOf(c);
  const power = list => fmtN(coalPower(list), 0);
  return `<div class="card"><h3>🛡️ Amenaza que representas</h3><div class="kv"><span>Infamia</span><b class="${c.infamy > 30 ? 'bad' : ''}">${Math.round(c.infamy)}</b></div><div class="kv"><span>Expansión reciente</span><b>${Math.round(c.exp || 0)}</b></div>
    <div class="kv"><span>Índice de amenaza</span><b class="${th > 32 ? 'bad' : th > 20 ? 'warn' : 'good'}">${Math.round(th)}</b></div>${bar(th, 60, th > 32 ? 'bad' : 'warn')}
    <p class="hint">Cuando tu infamia y tus conquistas recientes suben (índice > 32), las potencias vecinas pueden <b>formar una coalición</b> para frenarte: sus miembros se acercan entre sí, empeoran sus relaciones contigo, <b>acuden a defender a tus víctimas</b> y su líder puede <b>abrirte crisis diplomáticas</b>. La infamia baja 0,7 al mes; las conquistas se olvidan poco a poco.</p>
    <div class="btnrow"><button data-act="coalinf" ${c.influence < 40 || c.infamy < 3 ? 'disabled' : ''}>🕊️ Campaña de imagen: −12 infamia (40 infl.)</button></div></div>
  ${mine.length ? mine.map(co => `<div class="war"><div class="warh">🛡️ <b>Coalición contra ti</b> <small class="dim">· ${co.age} meses · lidera ${G.C[co.leader].name}</small></div>
    <div class="kv"><span>Fuerza militar de la coalición</span><b>${power(co.members)} (tú ${fmtN(armyPower(c), 0)})</b></div><div class="wbar"><b style="width:${clamp(coalPower(co.members) / Math.max(1, coalPower(co.members) + armyPower(c)), 0, 1) * 100}%"></b></div>
    <table class="tbl"><thead><tr><th>Miembro</th><th class="r">Relación</th><th class="r">Poder</th><th></th></tr></thead><tbody>${co.members.map(m => `<tr><td>${flag(m, 'sm')} ${G.C[m].name}${m === co.leader ? ' 👑' : ''}</td><td class="r">${Math.round(relOf(m, G.player))}</td><td class="r">${fmtN(armyPower(G.C[m]), 0)}</td><td class="r"><button data-act="coalapp" data-t="${m}" ${c.influence < 25 ? 'disabled' : ''}>🤝 Apaciguar (25 infl.)</button> <button data-act="coalbribe" data-t="${m}" ${c.treasury < c.stats.income * 10 ? 'disabled' : ''}>💰 Sobornar (${money(c.stats.income * 10)})</button></td></tr>`).join('')}</tbody></table></div>`).join('') : '<div class="card"><p class="hint">No hay coaliciones contra ti. ¡De momento!</p></div>'}
  <div class="card"><h3>Otras coaliciones en el mundo</h3>${others.length ? others.map(co => `<div class="kv sm"><span>Contra ${flag(co.target, 'sm')} ${G.C[co.target].name}: ${co.members.map(m => G.C[m].name).join(', ')}</span><b>${co.age} m.</b></div>`).join('') : '<small class="dim">Ninguna.</small>'}</div>`;
}
Object.assign(ACT, {
  coalinf: () => { const c = me(); if (c.influence >= 40) { c.influence -= 40; c.infamy = Math.max(0, c.infamy - 12); toast('🕊️', 'Campaña de imagen: baja tu infamia.'); } renderWindow(); },
  coalapp: d => { const c = me(); if (c.influence < 25) return; c.influence -= 25; addRel(G.player, d.t, 30); const co = coalitionOf(G.player); if (co && relOf(d.t, G.player) > 40 && Math.random() < 0.6) { co.members = co.members.filter(x => x !== d.t); toast('🤝', `${G.C[d.t].name} abandona la coalición.`); } else toast('🤝', `Mejoran las relaciones con ${G.C[d.t].name}.`); renderWindow(); },
  coalbribe: d => { const c = me(), cost = c.stats.income * 10; if (c.treasury < cost) return; c.treasury -= cost; const co = coalitionOf(G.player); if (co && Math.random() < 0.7) { co.members = co.members.filter(x => x !== d.t); toast('💰', `${G.C[d.t].name} acepta el soborno y abandona la coalición.`); } else toast('💰', `${G.C[d.t].name} cobra pero se queda en la coalición.`); renderWindow(); }
});

/* ===== TRANSPORTES Y PLANES DE DESEMBARCO (sin flota de guerra) ===== */
const TRANSPORT_CAP = 2, TRANSPORT_DAYS = 40, LAND_PREP = 14, LAND_RANGE = 75;
const shipsOf = c => (c.ships = c.ships || {transport: 0, busy: 0});
const freeTransports = c => { const s = shipsOf(c); return s.transport - s.busy; };
const transportCost = c => Math.round(moneyPerPoint(c) * 140);
function portStates(c) { return c.states.filter(id => MAP.stats[id].provs.some(p => MAP.provs[p].port)); }
function buildTransport(c, sid) {
  const s = G.S[sid]; if (!s || s.owner !== c.tag || !MAP.stats[sid].provs.some(p => MAP.provs[p].port)) return {ok: false, msg: 'Elige un estado propio con puerto.'};
  const cost = transportCost(c); if (c.treasury < cost) return {ok: false, msg: 'No tienes fondos para un transporte.'};
  c.treasury -= cost; G.shipQ = G.shipQ || []; G.shipQ.push({tag: c.tag, state: sid, days: TRANSPORT_DAYS});
  return {ok: true, msg: `Transporte en construcción en ${s.name} (${TRANSPORT_DAYS} días).`};
}
function portProvOf(sid) { const ps = MAP.stats[sid].provs.filter(p => MAP.provs[p].port); return ps.length ? ps[0] : null; }
// ¿puede desembarcar el ejército en la provincia destino?
function landingTargetOk(tag, pid) {
  const p = MAP.provs[pid]; if (!p.port) return 'Solo se puede desembarcar en provincias costeras.';
  const o = provOwner(pid);
  if (o === tag || sameSide(tag, o)) return null;
  if (o === NONE || hostileTags(tag, o)) return null;
  return 'Solo puedes desembarcar en costas enemigas, sin dueño o aliadas.';
}
function createLanding(tag, armyIds, to) {
  G.landings = G.landings || []; G.nextLand = G.nextLand || 1;
  const arms = armyIds.map(armyById).filter(a => a && a.tag === tag);
  if (!arms.length) return {ok: false, msg: 'Selecciona al menos un ejército.'};
  const err = landingTargetOk(tag, to); if (err) return {ok: false, msg: err};
  const from = arms[0].loc; if (!MAP.provs[from].port || !controlled(tag, from)) return {ok: false, msg: 'Los ejércitos deben estar en una provincia con puerto propio.'};
  if (provDist(from, to) > LAND_RANGE) return {ok: false, msg: 'El destino está demasiado lejos para los transportes.'};
  const divs = arms.reduce((n, a) => n + a.divs.length, 0), need = Math.ceil(divs / TRANSPORT_CAP);
  const L = {id: G.nextLand++, tag, armies: arms.map(a => a.id), from, to, phase: 'prep', prep: 0, active: false, need, auto: true};
  G.landings.push(L); arms.forEach(a => { a.landing = L.id; a.joinTo = null; a.front = null; });
  return {ok: true, land: L, need};
}
function cancelLanding(L) {
  (G.landings || []).forEach(x => { if (x === L) x.cancel = true; });
  L.armies.forEach(id => { const a = armyById(id); if (a && a.landing === L.id && !a.sea) a.landing = null; });
  G.landings = G.landings.filter(x => x !== L);
}
function startLanding(L) {   // embarca y zarpa
  const c = G.C[L.tag], arms = L.armies.map(armyById).filter(a => a && a.loc === L.from && !a.battle);
  if (!arms.length) return {ok: false, msg: 'Ningún ejército está en el puerto de embarque.'};
  const divs = arms.reduce((n, a) => n + a.divs.length, 0), need = Math.ceil(divs / TRANSPORT_CAP);
  if (freeTransports(c) < need) return {ok: false, msg: `Faltan transportes: necesitas ${need} y hay ${freeTransports(c)} libres.`};
  shipsOf(c).busy += need;
  const days = Math.ceil(provDist(L.from, L.to) * 4 + 5);
  arms.forEach(a => { a.sea = {plan: L.id, from: L.from, to: L.to, left: days, total: days}; a.path = []; a.dest = null; a.mode = null; });
  L.phase = 'sea'; L.left = days; L.carried = arms.map(a => a.id); L.need = need; L.active = true;
  G.shipReturns = G.shipReturns || []; G.shipReturns.push({tag: L.tag, n: need, days: days * 2 + 2});
  if (L.tag === G.player) notify('war', `Los transportes zarpan hacia ${provName(L.to)} (${days} días).`, provState(L.to));
  return {ok: true};
}
function landingDay() {
  const q = G.shipQ || [];
  for (let i = q.length - 1; i >= 0; i--) { if (--q[i].days <= 0) { const c = G.C[q[i].tag]; if (c && c.states.length) { shipsOf(c).transport++; if (c.tag === G.player) notify('build', `Un transporte ha sido botado en ${G.S[q[i].state].name}.`); } q.splice(i, 1); } }
  const rt = G.shipReturns || [];
  for (let i = rt.length - 1; i >= 0; i--) { if (--rt[i].days <= 0) { const c = G.C[rt[i].tag]; if (c) shipsOf(c).busy = Math.max(0, shipsOf(c).busy - rt[i].n); rt.splice(i, 1); } }
  (G.landings || []).slice().forEach(L => {
    const c = G.C[L.tag]; if (!c || !c.states.length) { G.landings = G.landings.filter(x => x !== L); return; }
    L.armies = L.armies.filter(id => armyById(id));
    if (L.phase === 'prep') {
      if (!L.active) return;
      const arms = L.armies.map(armyById);
      arms.forEach(a => { if (a.loc !== L.from && !a.path.length && !a.battle && !a.sea) { const r = orderMove(a, L.from, true); if (!r.ok) L.armies = L.armies.filter(x => x !== a.id); } else if (a.loc === L.from && !a.path.length && a.mode !== 'dig') a.mode = 'hold'; });
      if (arms.some(a => a.loc === L.from)) L.prep++;
      if (L.prep >= LAND_PREP && arms.filter(a => a.loc === L.from).length >= Math.max(1, Math.ceil(arms.length * 0.6))) {
        const r = startLanding(L); if (!r.ok) { if (L.tag === G.player && L.prep % 15 === 8) notify('war', `Desembarco en ${provName(L.to)}: ${r.msg}`); }
      }
    } else if (L.phase === 'sea') {
      let any = false;
      L.carried.forEach(id => { const a = armyById(id); if (!a || !a.sea) return; any = true; if (typeof navalLandingAttrition === 'function') { navalLandingAttrition(a); if (a._dead) { G.armies = G.armies.filter(x => x !== a); return; } } if (--a.sea.left <= 0) landArmy(a, L); });
      if (!any) { G.landings = G.landings.filter(x => x !== L); }
    }
  });
}
function landArmy(a, L) {
  const to = a.sea.to; a.sea = null; a.landing = null; a.loc = to; a.from = null; a.arrived = G.date.t; a.landed = G.date.t; a.rest = 0; a.dig = 0; a.mode = null;
  a.divs.forEach(d => { d.o *= 0.55; });
  G.beach = G.beach || {}; (G.beach[a.tag] = G.beach[a.tag] || {})[to] = G.date.t + 45;
  if (a.tag === G.player || provOwner(to) === G.player) notify('war', `¡${a.name} desembarca en ${provName(to)}!`, provState(to));
  else logMsg(`${G.C[a.tag].name} desembarca en ${provName(to)}.`);
}
// cabezas de playa: suministro por mar durante 45 días
function beachSupply(tag) { const b = G.beach && G.beach[tag], out = []; if (!b) return out; for (const pid in b) { if (b[pid] > G.date.t) out.push(+pid); else delete b[pid]; } return out; }
function aiLanding(c) {
  if (!c.ai || !c.wars.length || (G.landings || []).some(l => l.tag === c.tag)) return;
  const enemies = G.tags.filter(o => hostileTags(c.tag, o) && alive(o)); if (!enemies.length) return;
  const idle = armiesOf(c.tag).filter(a => !a.battle && !a.path.length && !a.sea && MAP.provs[a.loc].port && controlled(c.tag, a.loc) && a.divs.length >= 3);
  if (!idle.length) return;
  // provincias enemigas costeras a las que no se llega por tierra
  const land = new Set(); armiesOf(c.tag).forEach(a => { const q = [a.loc]; land.add(a.loc); for (let i = 0; i < q.length && i < 900; i++) MAP.provs[q[i]].nb.forEach(n => { if (!land.has(n) && canEnter(c.tag, n)) { land.add(n); q.push(n); } }); });
  const src = idle[0]; let best = null, bd = 1e9;
  enemies.forEach(e => G.C[e].states.forEach(sid => MAP.stats[sid].provs.forEach(p => { if (!MAP.provs[p].port || land.has(p) || G.P[p].by) return; const d = provDist(src.loc, p); if (d < bd && d <= LAND_RANGE) { bd = d; best = p; } })));
  if (best === null) return;
  const need = Math.ceil(src.divs.length / TRANSPORT_CAP);
  if (freeTransports(c) < need) { if ((G.shipQ || []).filter(q => q.tag === c.tag).length < 2 && c.treasury > transportCost(c) * 2) { const ps = portStates(c); if (ps.length) buildTransport(c, pick(ps)); } return; }
  const r = createLanding(c.tag, [src.id], best); if (r.ok) r.land.active = true;
}
function aiLandingWeek() { G.tags.forEach(t => { if (t !== NONE) aiLanding(G.C[t]); }); }

/* ---------- interfaz ---------- */
function landingsHtml() {
  const c = me(), ships = shipsOf(c), mine = (G.landings || []).filter(l => l.tag === G.player), ps = portStates(c).slice(0, 8);
  return `<div class="card"><h3>⚓ Planes de desembarco</h3><p class="hint">Selecciona un ejército que esté en una provincia con puerto y pulsa <b>⚓ Desembarco</b>; luego haz clic en una costa enemiga, una isla o una costa sin dueño. Los ejércitos se concentran en el puerto, embarcan en los <b>transportes</b> y desembarcan algo desorganizados (−45% organización y −25% de ataque durante 6 días). Sin puerto propio cerca recibirán suministro por mar solo 45 días.</p>
    ${mine.length ? mine.map(l => { const arms = l.armies.map(armyById).filter(Boolean); return `<div class="card front attack"><div class="kv"><b>⚓ ${provName(l.from)} ➜ ${provName(l.to)}</b>${l.phase === 'sea' ? `<span class="tag">⛴ En el mar · ${l.left} d</span>` : l.active ? `<span class="tag warn">⏳ Preparando ${l.prep}/${LAND_PREP} d</span>` : '<span class="tag">⏸ Sin activar</span>'}</div>
      <div class="kv sm"><span>Ejércitos</span><b>${arms.length} · ${arms.reduce((n, a) => n + a.divs.length, 0)} div. · ${l.need || Math.ceil(arms.reduce((n, a) => n + a.divs.length, 0) / TRANSPORT_CAP)} transportes</b></div>
      <div class="btnrow">${l.phase === 'prep' ? `<button data-act="landgo" data-id="${l.id}" class="${l.active ? '' : 'primary'}">${l.active ? '⏸ Pausar' : '▶ Activar plan'}</button>` : ''}<button data-act="landfocus" data-id="${l.id}">📍 Destino</button>${l.phase === 'prep' ? `<button data-act="landdel" data-id="${l.id}">✖ Cancelar</button>` : ''}</div></div>`; }).join('') : '<small class="dim">No hay desembarcos planeados.</small>'}</div>
  <div class="card"><h3>Transportes</h3><div class="kv"><span>Flota de transporte</span><b>${ships.transport} (${freeTransports(c)} libres) · capacidad ${TRANSPORT_CAP} div. cada uno</b></div><div class="kv sm"><span>En construcción</span><b>${(G.shipQ || []).filter(q => q.tag === G.player).length}</b></div>
    ${ps.length ? ps.map(id => `<div class="kv sm"><span>${G.S[id].name}</span><button data-act="buildship" data-id="${id}" ${c.treasury < transportCost(c) ? 'disabled' : ''}>＋ Transporte (${money(transportCost(c))})</button></div>`).join('') : '<small class="dim">No tienes estados con puerto.</small>'}</div>`;
}
Object.assign(ACT, {
  landmode: () => { const a = armyById(UI.selArmy); if (!a || !MAP.provs[a.loc].port) { toast('⚠️', 'El ejército debe estar en una provincia con puerto.'); return; } UI.landNext = !UI.landNext; UI.moveMode = UI.patrolNext = false; document.body.classList.toggle('movemode', UI.landNext); if (UI.landNext) toast('⚓', 'Haz clic en la costa de destino (enemiga, isla o sin dueño).'); renderArmyPanel(); },
  landgo: d => { const L = (G.landings || []).find(x => x.id === +d.id); if (L) { L.active = !L.active; renderWindow(); } },
  landdel: d => { const L = (G.landings || []).find(x => x.id === +d.id); if (L) { cancelLanding(L); renderWindow(); R.labelsDirty = true; } },
  landfocus: d => { const L = (G.landings || []).find(x => x.id === +d.id); if (L) focusProv(L.to, 35); },
  buildship: d => { const r = buildTransport(me(), +d.id); toast(r.ok ? '⚓' : '⚠️', r.msg); renderWindow(); }
});
function landClick(pid) {
  UI.landNext = false; document.body.classList.remove('movemode');
  const list = selectedArmies(); const r = createLanding(G.player, list.map(a => a.id), pid);
  if (!r.ok) { toast('⚠️', r.msg); renderArmyPanel(); return; }
  toast('⚓', `Plan de desembarco creado en ${provName(pid)}: ${r.need} transportes. Actívalo en Ejército → Frentes.`);
  UI.winTab.mil = 'fronts'; UI.win = null; openWindow('military'); R.labelsDirty = true;
}

/* ===== NIEBLA DE GUERRA E INTELIGENCIA =====
   - Al empezar sólo conoces parte del mundo: cuanto mayor es tu país, mayor es el radio explorado.
   - Las tropas de otros países sólo se ven en territorio propio/aliado, junto a tus ejércitos o a través de una red de agentes.
   - El servicio de inteligencia avisa de ataques, extiende la vista y permite robar tácticas al rival. */
const INTEL_LEVELS = [
  {name: 'Sin servicio', cost: 0, desc: 'No inviertes en espionaje.'},
  {name: 'Oficina de información', cost: 0.008, desc: '2 agentes. Avisa de ataques de la IA contra ti con unos días de antelación.'},
  {name: 'Servicio de inteligencia', cost: 0.016, desc: '4 agentes. Detecta tropas a 2 provincias de tu frontera.'},
  {name: 'Agencia de espionaje', cost: 0.028, desc: '6 agentes. Puede frustrar planes de ataque contra ti.'},
  {name: 'Red de espionaje mundial', cost: 0.045, desc: '8 agentes. Mayor alcance de vigilancia y espionaje más eficaz.'},
  {name: 'Servicio secreto imperial', cost: 0.07, desc: '10 agentes. Máxima eficacia en todo.'}
];
const INTEL_STEAL_DAYS = 60;
function intelOf(c) {
  if (!c.intel) c.intel = {lvl: c.ai ? (c.rank <= 8 ? 3 : c.rank <= 22 ? 2 : 1) : 0, ag: {}, steal: {}, miss: [], alert: {}};
  return c.intel;
}
const intelAgents = c => intelOf(c).lvl * 2;
const intelUsed = c => Object.values(intelOf(c).ag).reduce((s, n) => s + n, 0);
// fuerza de la red de agentes de `tag` dentro de `t` (0..1)
function intelNet(tag, t) {
  const c = G.C[tag]; if (!c) return 0; const I = intelOf(c), n = I.ag[t] || 0; if (!n) return 0;
  return clamp(Math.min(1, n * 0.34) * (0.7 + 0.06 * I.lvl) * (1 - 0.1 * intelOf(G.C[t]).lvl), 0, 1);
}
const intelReveals = (tag, t) => intelNet(tag, t) >= 0.2;

/* ---------- niebla ---------- */
function fogInit() {
  const N = MAP.provs.length, seen = new Uint8Array(N), c = G.C[G.player];
  const nT = G.tags.filter(t => t !== NONE && G.C[t].states.length).length, pct = 1 - (Math.min(c.rank, nT) - 1) / Math.max(1, nT - 1);
  const rad = 10 + 110 * Math.pow(clamp(1 - (c.rank - 1) / 35, 0, 1), 1.2); void pct;
  const own = []; c.states.forEach(sid => MAP.stats[sid].provs.forEach(p => own.push(p)));
  MAP.provs.forEach(P => { let d = 1e9; for (let i = 0; i < own.length; i++) { const q = MAP.provs[own[i]], dd = Math.hypot(P.lon - q.lon, P.lat - q.lat); if (dd < d) d = dd; } if (d <= rad) seen[P.id] = 1; });
  own.forEach(p => { seen[p] = 1; MAP.provs[p].nb.forEach(q => { seen[q] = 1; }); });
  G.fog = {p: G.player, seen, rad: Math.round(rad)};
  G.vis = null; R.needPaint = true;
}
function fogUpdate() {
  if (!G.player || !MAP.provs) return;
  if (!G.fog || G.fog.p !== G.player || G.fog.seen.length !== MAP.provs.length) fogInit();
  const me = G.player, c = G.C[me], I = intelOf(c), N = MAP.provs.length;
  const vis = G.vis && G.vis.length === N ? G.vis.fill(0) : (G.vis = new Uint8Array(N));
  const ring = (p, d) => { vis[p] = 1; if (d <= 0) return; MAP.provs[p].nb.forEach(q => { if (!vis[q] || d > 1) ring(q, d - 1); vis[q] = 1; }); };
  const depth = 1 + (I.lvl >= 2 ? 1 : 0) + (I.lvl >= 4 ? 1 : 0);
  for (let p = 0; p < N; p++) {
    const o = G.S[MAP.provs[p].s].owner, by = G.P[p].by;
    if ((o !== NONE && (o === me || sameSide(me, o))) || (by && sameSide(me, by))) { vis[p] = 1; if (o === me || (by && sameSide(me, by))) MAP.provs[p].nb.forEach(q => { vis[q] = 1; if (depth > 1) MAP.provs[q].nb.forEach(r => { vis[r] = 1; if (depth > 2) MAP.provs[r].nb.forEach(s => { vis[s] = 1; }); }); }); }
  }
  G.armies.forEach(a => { if (a.sea || !sameSide(me, a.tag)) return; vis[a.loc] = 1; MAP.provs[a.loc].nb.forEach(q => { vis[q] = 1; }); if (a.divs.some(d => d.t === 'cav')) MAP.provs[a.loc].nb.forEach(q => MAP.provs[q].nb.forEach(r => { vis[r] = 1; })); });
  if (typeof airReconRegs === 'function' && G.mx) airReconRegs(me).forEach(r => airReg(r).states.forEach(sid => MAP.stats[sid].provs.forEach(p => { vis[p] = 1; })));
  for (const t in I.ag) if (intelReveals(me, t) && G.C[t]) G.C[t].states.forEach(sid => MAP.stats[sid].provs.forEach(p => { vis[p] = 1; }));
  let fresh = 0; for (let p = 0; p < N; p++) if (vis[p] && !G.fog.seen[p]) { G.fog.seen[p] = 1; fresh++; }
  if (fresh) R.needPaint = true;
  void ring;
}
function armyVisible(a) {
  if (!G.fog || !G.player || R.fogOff) return true;
  if (a.tag === G.player || sameSide(G.player, a.tag)) return true;
  if (a.sea) return !!(G.vis && (G.vis[a.sea.from] || G.vis[a.sea.to]));
  return !G.vis || !!G.vis[a.loc];
}
const provVisible = pid => !G.fog || !G.vis || R.fogOff || !!G.vis[pid];

/* ---------- tareas diarias / semanales / mensuales ---------- */
function intelDay() {
  if (!G.player || !G.C[G.player]) return;
  if (!G.fog || (G.date.t % 2) === 0) fogUpdate();
  const I = intelOf(G.C[G.player]);
  if (typeof spyDay === 'function') spyDay();
  I.miss = I.miss.filter(m => {
    if (G.date.t < m.end) return true;
    const t = G.C[m.t], p = clamp(0.3 + 0.11 * I.lvl + 0.25 * intelNet(G.player, m.t) - 0.07 * intelOf(t).lvl, 0.1, 0.92);
    if (Math.random() < p) { I.steal[m.t] = G.date.t + INTEL_STEAL_DAYS; notify('war', `🕵️ ¡Tus agentes han obtenido los planes tácticos de ${t.name}! Durante ${INTEL_STEAL_DAYS} días tus ejércitos combaten mejor contra ellos.`); }
    else { I.ag[m.t] = Math.max(0, (I.ag[m.t] || 0) - 1); addRel(G.player, m.t, -15); notify('war', `🕵️ La misión de espionaje contra ${t.name} fracasó: un agente fue capturado y las relaciones empeoran.`); }
    return false;
  });
}
function intelWeek() {
  const c = G.C[G.player]; if (!c) return; const I = intelOf(c);
  // ataques de la IA en preparación
  G.pendAtt = (G.pendAtt || []).filter(p => {
    if (G.date.t < p.at) return true;
    const A = G.C[p.a]; if (!alive(p.a) || !alive(p.d) || A.wars.length || relOf(p.a, p.d) > 40) { if (alive(p.a)) notify('diplo', `🕵️ ${A.name} renuncia a atacarte.`); return false; }
    declareWar(p.a, p.d, p.cb, p.targets, {free: p.fr}); return false;
  });
  // concentración de tropas junto a la frontera
  if (I.lvl >= 1 && c.states.length) {
    const near = new Set(); c.states.forEach(sid => MAP.stats[sid].provs.forEach(p => { near.add(p); MAP.provs[p].nb.forEach(q => { near.add(q); if (I.lvl >= 2) MAP.provs[q].nb.forEach(r => near.add(r)); }); }));
    const cnt = {}; G.armies.forEach(a => { if (a.sea || a.tag === G.player || sameSide(G.player, a.tag) || !near.has(a.loc)) return; if (!(I.lvl >= 2 || intelReveals(G.player, a.tag) || (G.vis && G.vis[a.loc]))) return; cnt[a.tag] = (cnt[a.tag] || 0) + a.divs.length; });
    for (const t in cnt) if (cnt[t] >= 4 && G.date.t - (I.alert[t] || -99) > 40) { I.alert[t] = G.date.t; notify('war', `🕵️ Inteligencia: ${G.C[t].name} concentra ${cnt[t]} divisiones junto a tu frontera.`); }
  }
}
function intelMonth(c) {
  const I = intelOf(c);
  if (c.ai) return;
  c.treasury -= Math.max(0, c.stats.income) * INTEL_LEVELS[I.lvl].cost * 4.3;
  if (I.lvl === 0) { for (const t in I.ag) delete I.ag[t]; }
  else for (const t in I.ag) { // el exceso de agentes se retira y algunos son capturados
    const lim = intelAgents(c); while (intelUsed(c) > lim) { const k = Object.keys(I.ag).find(x => I.ag[x] > 0); if (!k) break; I.ag[k]--; }
    for (let i = 0; i < (I.ag[t] || 0); i++) if (Math.random() < 0.012 * intelOf(G.C[t]).lvl * (1 - 0.1 * I.lvl)) { I.ag[t]--; addRel(c.tag, t, -6); notify('war', `🕵️ Un agente tuyo ha sido capturado en ${G.C[t].name}. Las relaciones empeoran.`); break; }
    if (!I.ag[t]) delete I.ag[t];
  }
}
// la IA va a atacar al jugador: el servicio de inteligencia avisa (y quizá lo frustra)
function intelAiAttack(a, d, cb, targets, fr) {
  if (d !== G.player) return false; const I = intelOf(G.C[d]); if (I.lvl < 1) return false;
  if (I.lvl >= 3 && Math.random() < 0.15 * (I.lvl - 2)) { notify('diplo', `🕵️ Tus agentes han frustrado un plan de ataque de ${G.C[a].name}.`); return true; }
  const days = 8 + I.lvl * 4; (G.pendAtt = G.pendAtt || []).push({a, d, cb, targets, fr, at: G.date.t + days});
  notify('diplo', `🕵️ Tus agentes advierten: ${G.C[a].name} prepara un ataque contra ti en unos ${days} días. Moviliza tropas o mejora las relaciones.`);
  return true;
}
/* ---------- acciones del jugador ---------- */
function intelSetLevel(c, n) { const I = intelOf(c); I.lvl = clamp(n | 0, 0, 5); while (intelUsed(c) > intelAgents(c)) { const k = Object.keys(I.ag).find(x => I.ag[x] > 0); I.ag[k]--; if (!I.ag[k]) delete I.ag[k]; } }
function intelSend(c, t) { const I = intelOf(c); if (intelUsed(c) >= intelAgents(c)) return {ok: false, msg: 'No tienes agentes libres. Sube el nivel del servicio.'}; if ((I.ag[t] || 0) >= 3) return {ok: false, msg: 'Ya hay 3 agentes allí.'}; I.ag[t] = (I.ag[t] || 0) + 1; G.vis = null; fogUpdate(); return {ok: true, msg: `Un agente parte hacia ${G.C[t].name}.`}; }
function intelRecall(c, t) { const I = intelOf(c); if (!I.ag[t]) return {ok: false, msg: ''}; I.ag[t]--; if (!I.ag[t]) delete I.ag[t]; return {ok: true, msg: `Un agente regresa de ${G.C[t].name}.`}; }
const stealCost = c => Math.round(Math.max(0, c.stats.income) * 0.25);
function intelSteal(c, t) {
  const I = intelOf(c); if (!(I.ag[t] > 0)) return {ok: false, msg: 'Necesitas al menos un agente en ese país.'};
  if (I.miss.some(m => m.t === t)) return {ok: false, msg: 'Ya hay una misión en curso allí.'};
  if (c.treasury < stealCost(c)) return {ok: false, msg: 'No tienes fondos para la operación.'};
  c.treasury -= stealCost(c); I.miss.push({t, end: G.date.t + 20});
  return {ok: true, msg: `Tus agentes en ${G.C[t].name} intentan robar sus planes tácticos (20 días).`};
}
const intelStealBonus = (tag, foe) => { const c = G.C[tag]; return c && c.intel && foe && c.intel.steal && c.intel.steal[foe] > G.date.t ? 0.12 : 0; };

/* ---------- pestaña de la interfaz ---------- */
function intelTabHtml() {
  const c = me(), I = intelOf(c), free = intelAgents(c) - intelUsed(c);
  const myProvs = new Set(); c.states.forEach(sid => MAP.stats[sid].provs.forEach(p => myProvs.add(p)));
  const rel = G.tags.filter(t => t !== NONE && t !== G.player && alive(t)).map(t => {
    let near = 0; G.C[t].states.forEach(sid => MAP.stats[sid].provs.forEach(p => { if (MAP.provs[p].nb.some(q => myProvs.has(q))) near = 1; }));
    return {t, sc: (near ? 100 : 0) + (hostileTags(G.player, t) ? 150 : 0) + (I.ag[t] ? 200 : 0) + (60 - Math.min(60, G.C[t].rank * 3))};
  }).sort((a, b) => b.sc - a.sc).slice(0, 18);
  return `<div class="cols"><div class="col"><div class="card"><h3>🕵️ Servicio de inteligencia</h3>
    <p class="hint">Cuanto más inviertas, más agentes tienes y más lejos ves. Coste mensual: <b>${money(Math.max(0, c.stats.income) * INTEL_LEVELS[I.lvl].cost * 4.3)}</b>.</p>
    ${INTEL_LEVELS.map((l, i) => `<button class="block ${I.lvl === i ? 'on' : ''}" data-act="intellvl" data-n="${i}"><b>${l.name}</b> <small>${i ? Math.round(l.cost * 1000) / 10 + '% de los ingresos' : 'gratis'}</small><small class="dim">${l.desc}</small></button>`).join('')}
    <div class="kv"><span>Agentes libres</span><b>${free} / ${intelAgents(c)}</b></div>
    <div class="kv"><span>Mundo explorado</span><b>${G.fog ? Math.round(G.fog.seen.reduce((s, x) => s + x, 0) / G.fog.seen.length * 100) : 0}%</b></div></div></div>
    <div class="col wide"><div class="card"><h3>Agentes en el extranjero</h3><p class="hint">Dos agentes en un país te dan <b>visión completa</b> de su territorio y sus ejércitos. Con un agente puedes <b>robar sus tácticas</b>: durante ${INTEL_STEAL_DAYS} días tus tropas atacan y defienden un 12% mejor contra ellos. Los países con buen servicio de inteligencia descubren a tus agentes.</p>
    <table class="tbl"><thead><tr><th>País</th><th class="r">Agentes</th><th class="r">Red</th><th></th></tr></thead><tbody>${rel.map(r => { const n = I.ag[r.t] || 0, st = I.steal[r.t] > G.date.t, ms = I.miss.some(m => m.t === r.t); return `<tr><td>${flag(r.t, 'sm')} <b>${G.C[r.t].name}</b> <small class="dim">${hostileTags(G.player, r.t) ? '⚔ en guerra' : ''} · inteligencia ${intelOf(G.C[r.t]).lvl}</small></td><td class="r">${n}</td><td class="r">${Math.round(intelNet(G.player, r.t) * 100)}%</td><td class="r"><button data-act="intelsend" data-t="${r.t}" ${free > 0 && n < 3 ? '' : 'disabled'}>＋</button> <button data-act="intelrecall" data-t="${r.t}" ${n ? '' : 'disabled'}>－</button> <button data-act="intelsteal" data-t="${r.t}" ${n && !ms ? '' : 'disabled'} data-tip="Cuesta ${money(stealCost(c))}">${st ? '✔ tácticas robadas (' + (I.steal[r.t] - G.date.t) + ' d)' : ms ? 'en curso…' : '📜 Robar tácticas'}</button></td></tr>`; }).join('')}</tbody></table></div>${typeof spyCardHtml === 'function' ? spyCardHtml(c, I) : ''}</div></div>`;
}
Object.assign(ACT, {
  intellvl: d => { intelSetLevel(me(), +d.n); renderWindow(); },
  intelsend: d => { const r = intelSend(me(), d.t); toast(r.ok ? '🕵️' : '⚠️', r.msg); renderWindow(); },
  intelrecall: d => { const r = intelRecall(me(), d.t); if (r.msg) toast('🕵️', r.msg); renderWindow(); },
  intelsteal: d => { const r = intelSteal(me(), d.t); toast(r.ok ? '📜' : '⚠️', r.msg); renderWindow(); }
});

/* ===== ESPIONAJE OFENSIVO =====
   Con agentes en un país puedes lanzar operaciones encubiertas (necesitan unos días y dinero):
   · Sabotaje industrial: destruye parte de la industria de su estado más industrial y reduce su producción durante meses.
   · Financiar rebeldes: más radicales, menos legitimidad y más riesgo de guerra civil (si estalla, los rebeldes te deben el favor).
   · Robar tecnología: te llevas una tecnología que él tiene y tú no.
   La contrainteligencia protege tu país. La IA también espía (si la regla «Espionaje enemigo» está activa). */
const SPY_OPS = {
  sabotage: {name: 'Sabotaje industrial', icon: '🔥', cost: 0.30, days: 25, hostile: true, desc: 'Destruye parte de la industria de su estado más industrial (−12%) y reduce su producción 3 meses.'},
  rebels: {name: 'Financiar rebeldes', icon: '🎭', cost: 0.40, days: 30, hostile: true, desc: 'Más radicales, −4 legitimidad y más riesgo de guerra civil en el país objetivo.'},
  tech: {name: 'Robar tecnología', icon: '📚', cost: 0.50, days: 40, hostile: false, desc: 'Obtienes una tecnología que el objetivo tiene y tú no.'}
};
const SPY_COUNTER_DAYS = 365;
const spyCost = (c, k) => Math.round(Math.max(1, c.stats.income) * SPY_OPS[k].cost);
const counterBonus = t => { const c = G.C[t]; return c ? ((c.counterUntil || 0) > G.date.t ? 0.2 : 0) + 0.02 * intelOf(c).lvl : 0; };
// probabilidad de éxito de una operación de `from` sobre `to` (con `agents` agentes sobre el terreno)
function spyChance(from, to, agents) {
  const I = intelOf(G.C[from]);
  return clamp(0.30 + 0.10 * I.lvl + 0.12 * Math.max(0, (agents || 1) - 1) + 0.2 * intelNet(from, to) - 0.09 * intelOf(G.C[to]).lvl - counterBonus(to), 0.08, 0.9);
}
function spyTechPick(c, T) { const l = TECHS.filter(t => T.techs.has(t.id) && !c.techs.has(t.id) && techAvailable(c, t)); return l.length ? pick(l) : null; }
// aplica el efecto de una operación que ha tenido éxito; devuelve el texto
function spyApply(kind, from, to) {
  const F = G.C[from], T = G.C[to];
  if (kind === 'sabotage') {
    const ind = s => BUILDINGS.reduce((n, b) => n + ((b.grp === 'Industria' || b.grp === 'Industria militar') ? (s.b[b.id] || 0) : 0), 0);
    const sid = T.states.slice().sort((a, b) => ind(G.S[b]) - ind(G.S[a]))[0];
    if (sid === undefined) return null;
    const s = G.S[sid]; BUILDINGS.forEach(b => { if ((b.grp === 'Industria' || b.grp === 'Industria militar') && s.b[b.id] > 0) s.b[b.id] *= 0.88; });
    addTimedFx(T, 'Sabotaje', '🔥', {ind: 0.97}, 3, 'Atentados e incendios en las fábricas.'); T.legitimacy = Math.max(0, T.legitimacy - 1);
    return {txt: `sabotea la industria de ${s.name}`, txtP: `sabotean la industria de ${s.name}`, st: s.name};
  }
  if (kind === 'rebels') {
    T.radicals = Math.min(0.9, T.radicals + 0.05); T.legitimacy = Math.max(0, T.legitimacy - 4); T.lowLeg = (T.lowLeg || 0) + 2; T.cwSupport = (T.cwSupport || 0) + 1; T.cwSponsor = from;
    return {txt: 'financia a los rebeldes', txtP: 'financian a los rebeldes'};
  }
  if (kind === 'tech') {
    const t = spyTechPick(F, T); if (!t) return null;
    F.techs.add(t.id); if (F.research === t.id) F.research = null; recalcMods(F);
    return {txt: `roba la tecnología «${t.name}»`, txtP: `roban la tecnología «${t.name}»`};
  }
  return null;
}
// resuelve una operación: éxito/fracaso, detección y consecuencias diplomáticas
function spyResolve(from, to, kind, agents, instant) {
  const F = G.C[from], T = G.C[to], op = SPY_OPS[kind], p = spyChance(from, to, agents), I = intelOf(F);
  const mine = from === G.player, theirs = to === G.player;
  if (Math.random() < p) {
    const r = spyApply(kind, from, to);
    if (!r) { if (mine) notify('war', `🕵️ La operación «${op.name}» contra ${T.name} no encontró nada que hacer.`); return false; }
    const det = op.hostile && Math.random() < 0.25 + 0.08 * intelOf(T).lvl + counterBonus(to);
    if (det) { addRel(from, to, -30); F.infamy = (F.infamy || 0) + 3; }
    if (mine) notify('war', `🕵️ ¡Éxito! Tus agentes en ${T.name} ${r.txtP}.${det ? ' Pero han sido descubiertos: las relaciones se hunden.' : ''}`);
    if (theirs) notify('war', det ? `🕵️ Contrainteligencia: ${F.name} ${r.txt} en tu país. ¡Fue detectado!` : (kind === 'tech' ? '🕵️ Tus servicios sospechan que han robado un secreto tecnológico.' : `🕵️ Misterioso ${kind === 'sabotage' ? 'sabotaje' : 'brote de agitación'} en tu país${r.st ? ' (' + r.st + ')' : ''}. No se sabe quién lo ha organizado.`));
    return true;
  }
  if (!instant && I.ag[to]) { I.ag[to] = Math.max(0, I.ag[to] - 1); if (!I.ag[to]) delete I.ag[to]; }
  addRel(from, to, -15 - (op.hostile ? 10 : 0));
  if (mine) notify('war', `🕵️ La operación «${op.name}» contra ${T.name} fracasó: un agente fue capturado y las relaciones empeoran.`);
  if (theirs) notify('war', `🕵️ Tus servicios capturan a un agente de ${F.name} que preparaba «${op.name.toLowerCase()}».`);
  return false;
}

/* ---------- acciones del jugador ---------- */
function spyStart(c, to, kind) {
  const I = intelOf(c), op = SPY_OPS[kind]; if (!op) return {ok: false, msg: 'Operación desconocida.'};
  if (!(I.ag[to] > 0)) return {ok: false, msg: 'Necesitas al menos un agente en ese país.'};
  I.ops = I.ops || []; if (I.ops.some(o => o.t === to)) return {ok: false, msg: 'Ya hay una operación en curso allí.'};
  if (I.miss.some(m => m.t === to)) return {ok: false, msg: 'Tus agentes ya están ocupados robando tácticas.'};
  if (c.treasury < spyCost(c, kind)) return {ok: false, msg: `La operación cuesta ${money(spyCost(c, kind))} y no tienes fondos.`};
  c.treasury -= spyCost(c, kind); I.ops.push({t: to, k: kind, end: G.date.t + op.days, ag: I.ag[to]});
  return {ok: true, msg: `${op.icon} ${op.name} contra ${G.C[to].name} en marcha (${op.days} días, éxito ≈ ${Math.round(spyChance(c.tag, to, I.ag[to]) * 100)}%).`};
}
function spyCounter(c) {
  const cost = Math.round(Math.max(1, c.stats.income) * 0.6);
  if ((c.counterUntil || 0) > G.date.t) return {ok: false, msg: 'La contrainteligencia ya está activa.'};
  if (c.treasury < cost) return {ok: false, msg: `Cuesta ${money(cost)} y no tienes fondos.`};
  c.treasury -= cost; c.counterUntil = G.date.t + SPY_COUNTER_DAYS;
  return {ok: true, msg: '🛡️ Contrainteligencia reforzada durante un año: las operaciones enemigas fallan más y se detectan antes.'};
}
// llamado cada día para el jugador
function spyDay() {
  const c = G.C[G.player]; if (!c || !c.intel || !c.intel.ops || !c.intel.ops.length) return;
  c.intel.ops = c.intel.ops.filter(o => { if (G.date.t < o.end) return true; if (alive(o.t)) spyResolve(G.player, o.t, o.k, o.ag || 1, false); return false; });
}

/* ---------- IA y mantenimiento mensual ---------- */
function spyMonth() {
  G.tags.forEach(t => { if (t === NONE) return; const c = G.C[t]; if (c.cwSupport) c.cwSupport = Math.max(0, c.cwSupport * 0.9 - 0.02); if (c.cwSupport < 0.1) { c.cwSupport = 0; } });
  G.tags.forEach(t => {
    if (t === NONE) return; const c = G.C[t]; if (!c.ai || !c.states.length || c.rank > 30) return;
    const I = intelOf(c); if (I.lvl < 2 || Math.random() > 0.05 + 0.02 * (I.lvl - 2)) return;
    // objetivos: enemigos en guerra → sabotaje; rivales mal avenidos → rebeldes; potencias más avanzadas → robo de tecnología
    const rivals = G.tags.filter(x => x !== NONE && x !== t && alive(x) && !sameSide(t, x) && (x !== G.player || rule('spy')));
    const war = rivals.filter(x => hostileTags(t, x)), bad = rivals.filter(x => relOf(t, x) < -10 && G.C[x].states.length >= 6 && Math.abs(G.C[x].rank - c.rank) <= 12);
    const adv = rivals.filter(x => G.C[x].rank < c.rank && G.C[x].techs.size > c.techs.size && spyTechPick(c, G.C[x]));
    let kind = null, to = null;
    if (war.length) { kind = 'sabotage'; to = pick(war); }
    else if (adv.length && Math.random() < 0.5) { kind = 'tech'; to = pick(adv); }
    else if (bad.length && I.lvl >= 3) { kind = 'rebels'; to = pick(bad); }
    else if (adv.length) { kind = 'tech'; to = pick(adv); }
    if (kind && to) spyResolve(t, to, kind, 1, true);
  });
}

/* ---------- interfaz: tarjeta de operaciones (se inserta en la pestaña de inteligencia) ---------- */
function spyCardHtml(c, I) {
  const ops = I.ops || [], withAg = Object.keys(I.ag).filter(t => I.ag[t] > 0 && alive(t));
  const counter = (c.counterUntil || 0) > G.date.t;
  const rows = withAg.map(t => { const busy = ops.find(o => o.t === t), ms = I.miss.some(m => m.t === t);
    return `<tr><td>${flag(t, 'sm')} <b>${G.C[t].name}</b> <small class="dim">${I.ag[t]} ag.</small></td><td class="r">${busy ? `${SPY_OPS[busy.k].icon} ${SPY_OPS[busy.k].name} (${Math.max(0, busy.end - G.date.t)} d)` : Object.keys(SPY_OPS).map(k => `<button data-act="spyop" data-t="${t}" data-k="${k}" ${ms ? 'disabled' : ''} data-tip="<b>${SPY_OPS[k].name}</b><br>${SPY_OPS[k].desc}<br>Coste ${money(spyCost(c, k))} · éxito ≈ ${Math.round(spyChance(c.tag, t, I.ag[t]) * 100)}%">${SPY_OPS[k].icon}</button>`).join(' ')}</td></tr>`; }).join('');
  return `<div class="card"><h3>🕶️ Operaciones encubiertas</h3>
    <p class="hint">Con agentes en un país puedes lanzar <b>🔥 sabotaje</b>, <b>🎭 financiar rebeldes</b> (si estalla una guerra civil, los rebeldes te deberán el favor) o <b>📚 robar tecnología</b>. Fallar cuesta un agente y las relaciones; si te descubren, la infamia sube.</p>
    ${rows ? `<table class="tbl"><thead><tr><th>País</th><th class="r">Operación</th></tr></thead><tbody>${rows}</tbody></table>` : '<p class="hint">Envía agentes (＋) a un país para habilitar las operaciones.</p>'}
    <div class="kv"><span>🛡️ Contrainteligencia</span><b>${counter ? `activa (${Math.ceil(((c.counterUntil || 0) - G.date.t) / 30)} meses)` : `<button data-act="spycounter">Reforzar · ${money(Math.round(Math.max(1, c.stats.income) * 0.6))}</button>`}</b></div></div>`;
}
Object.assign(ACT, {
  spyop: d => { const r = spyStart(me(), d.t, d.k); toast(r.ok ? '🕶️' : '⚠️', r.msg); renderWindow(); },
  spycounter: () => { const r = spyCounter(me()); toast(r.ok ? '🛡️' : '⚠️', r.msg); renderWindow(); }
});

/* ===== MILITAR 2 · NÚCLEO =====
   Datos nuevos (bienes, edificios, tecnologías), estado ampliado de país y de partida, regiones aéreas, zonas marítimas,
   pestañas nuevas de la ventana militar y utilidades comunes de los módulos aviacion / marina / doctrinas / plantillas /
   produccion / resistencia / mariscales. Todo lo nuevo se guarda dentro de G.mx (partida) y c.m2 (país) con valores por defecto,
   de modo que las partidas antiguas siguen cargando. */
const MX_TABS = [];          // {id, label, html()}: pestañas añadidas a «Ejército y guerra»

/* ---------- bienes nuevos ---------- */
[
  {id: 'engines', name: 'Motores', base: 40, icon: '⚙️', color: '#8a8f99', cat: 'Industriales'},
  {id: 'aircraft', name: 'Aviones', base: 3500, icon: '✈️', color: '#b9c7d6', cat: 'Militares'},
  {id: 'mgs', name: 'Ametralladoras', base: 160, icon: '🔫', color: '#6c6f78', cat: 'Militares'},
  {id: 'ships', name: 'Tonelaje naval', base: 2200, icon: '⚓', color: '#4f7aa0', cat: 'Militares'}
].forEach(g => { if (!GOOD[g.id]) { GOODS.push(g); GOOD[g.id] = g; } });

/* ---------- edificios nuevos ---------- */
[
  {id: 'enginew', name: 'Fábricas de Motores', icon: '⚙️', grp: 'Industria militar', out: 'engines', inputs: {steel: 1500, tools: 600, coal: 400}, workers: {laborers: .7, machinists: .3}, cost: 420, cap: 'ind', tech: 'internal_comb'},
  {id: 'aeroworks', name: 'Fábricas Aeronáuticas', icon: '✈️', grp: 'Industria militar', out: 'aircraft', inputs: {steel: 1200, engines: 900, fabric: 1500}, workers: {laborers: .6, machinists: .4}, cost: 520, cap: 'ind', tech: 'military_aviation'},
  {id: 'mgworks', name: 'Fábricas de Ametralladoras', icon: '🔫', grp: 'Industria militar', out: 'mgs', inputs: {steel: 1400, tools: 500}, workers: {laborers: .75, machinists: .25}, cost: 360, cap: 'ind', tech: 'machine_guns'},
  {id: 'shipyard', name: 'Astilleros', icon: '⚓', grp: 'Industria militar', out: 'ships', inputs: {wood: 3000, iron: 900, cannons: 60, fabric: 600}, workers: {laborers: .75, machinists: .25}, cost: 400, cap: 'coast'}
].forEach(b => {
  if (BLD[b.id]) return;
  BUILDINGS.push(b); BLD[b.id] = b; b.workersPerLevel = WORKERS_PER_LEVEL;
  let iv = 0; for (const g in b.inputs) iv += b.inputs[g] * GOOD[g].base;
  b.outAmt = (iv + VA_PER_WORKER * b.workersPerLevel) / GOOD[b.out].base;
});
// tecnologías que la IA de las grandes potencias prioriza para tener aviación, marina y ejércitos modernos hacia 1914
const MIL_PRIORITY = new Set(['armor', 'chemical_weapons', 'steel_artillery', 'machine_guns', 'quick_firing', 'bessemer', 'machine_tools', 'electricity', 'internal_comb', 'military_aviation', 'fighters', 'bombers', 'motorization', 'steam_frigate', 'ironclad', 'cruisers', 'submarines', 'dreadnought', 'bolt_action', 'breech_loaders', 'general_staff', 'steamships', 'trench_warfare']);
const MIL_BUILDINGS = ['armory', 'foundry', 'powder', 'mgworks', 'aeroworks', 'shipyard', 'enginew'];

