  for (let i = 0, n = cnt(P.snow, 240); i < n; i++) { const [x, y] = pos(241 + i, 140); tf.snow.push({x, y, rx: 70 + H(260 + i) * 90, ry: 38 + H(275 + i) * 40, rot: 0}); }
